import heapq


class Solution:
    def kthLargestNumber(self, nums: List[str], k: int) -> str:
        heap = []
        for s in nums:
            heapq.heappush(heap, (len(s), s))
            if len(heap) > k:
                heapq.heappop(heap)
        return heap[0][1]

