var kthLargestNumber = function (nums, k) {
    const less = (a, b) => (a.length !== b.length ? a.length < b.length : a < b);
    const heapifyUp = (h) => {
        let i = h.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (!less(h[i], h[p])) break;
            [h[i], h[p]] = [h[p], h[i]];
            i = p;
        }
    };
    const push = (h, s) => { h.push(s); heapifyUp(h); };
    const pop = (h) => {
        const top = h[0], last = h.pop();
        if (h.length) {
            h[0] = last;
            let i = 0;
            for (;;) {
                const l = 2 * i + 1, r = l + 1;
                let m = i;
                if (l < h.length && less(h[l], h[m])) m = l;
                if (r < h.length && less(h[r], h[m])) m = r;
                if (m === i) break;
                [h[i], h[m]] = [h[m], h[i]];
                i = m;
            }
        }
        return top;
    };
    const heap = [];
    for (const s of nums) {
        push(heap, s);
        if (heap.length > k) pop(heap);
    }
    return heap[0];
};
